(() => {
'use strict';const c=window.HVT,$=s=>document.querySelector(s);let rows=[];
function show(id){const p=rows.find(p=>p.id===id);if(!p)return;const cover=c.cover(p);$('#postReaderContent').innerHTML='<p class="eyebrow">BÀI VIẾT · HIỂU VÀ THƯƠNG</p><h2>'+c.esc(p.title)+'</h2><p>'+c.esc(p.author)+'</p>'+(cover?'<img class="reader-cover" src="'+c.esc(cover)+'" alt="'+c.esc(p.title)+'">':'')+'<div class="rich-document">'+window.HVTRich.clean(p.body_html)+'</div>';$('#postReader').showModal()}
$('#postReader .close').onclick=()=>$('#postReader').close();$('#homePostCards').onclick=e=>{const b=e.target.closest('[data-open-post]');if(b)show(b.dataset.openPost)};
async function load(){if(!c.configured)return;try{rows=await c.publicApi('/rest/v1/home_posts?select=*&order=published_at.desc&limit=100');$('#homePostNotice').textContent=rows.length?'Những chia sẻ mới từ Hiểu và Thương.':'Những bài viết mới sẽ được gửi đến bạn tại đây.';$('#homePostCards').innerHTML=rows.map(p=>`<article class="card"><div class="card-art book-cover">${c.cover(p)?`<img src="${c.esc(c.cover(p))}" alt="${c.esc(p.title)}" loading="lazy">`:'<span>❋</span>'}</div><div class="card-body"><span class="tag">BÀI VIẾT</span><h3>${c.esc(p.title)}</h3><p>${c.esc(p.summary)}</p><p>${c.esc(p.author)}</p><button class="text-link" data-open-post="${c.esc(p.id)}">Đọc bài viết ↗</button></div></article>`).join('');const requested=new URLSearchParams(location.search).get('post');if(requested)show(requested)}catch{$('#homePostNotice').textContent='Chưa tải được bài viết mới. Vui lòng thử lại sau.'}}
load();
})();
